class Employee {
    protected String name;
    protected double basicSalary;

    public Employee(String name, double basicSalary) {
        this.name = name;
        this.basicSalary = basicSalary;
        System.out.println("[Parent] Employee constructor initialized: " + name);
    }
}

class Developer extends Employee {
    private String primaryLanguage;

    public Developer(String name, double basicSalary, String language) {
        // super() MUST be the very first statement!
        super(name, basicSalary);
        this.primaryLanguage = language;
        System.out.println("[Child] Developer constructor initialized with language: " + language);
    }

    public void displayProfile() {
        System.out.println("Dev Profile -> Name: " + name + ", Salary: $" + basicSalary + ", Language: " + primaryLanguage);
    }
}

public class SuperConstructorDemo {
    public static void main(String[] args) {
        Developer dev = new Developer("Alex Mercer", 92000.0, "Java");
        dev.displayProfile();
    }
}

