class Vehicle {
    int maxSpeed = 100;

    void displayInfo() {
        System.out.println("Vehicle base max speed: " + maxSpeed + " km/h");
    }
}

class SportsCar extends Vehicle {
    // Field Shadowing: declaring maxSpeed with the same name
    int maxSpeed = 260;

    @Override
    void displayInfo() {
        // 1. Calling parent's version of displayInfo()
        super.displayInfo();

        // 2. Differentiating between child and parent fields
        System.out.println("SportsCar tuned max speed: " + this.maxSpeed + " km/h");
        System.out.println("Original chassis rating was: " + super.maxSpeed + " km/h");
    }
}

public class SuperFieldDemo {
    public static void main(String[] args) {
        SportsCar car = new SportsCar();
        car.displayInfo();
    }
}

