class Book {
    String title;
    double price;

    public Book(String title, double price) {
        this.title = title;
        this.price = price;
    }
}

class Textbook extends Book {
    String subject;

    public Textbook(String title, double price, String subject) {
        super(title, price);
        this.subject = subject;
    }

    public void showDetails() {
        System.out.println(title + " (" + subject + ") - $" + price);
    }
}

public class Main {
    public static void main(String[] args) {
        Textbook tb = new Textbook("Linear Algebra", 89.99, "Mathematics");
        tb.showDetails();
    }
}

class Shape {
    String type = "Generic Shape";
}

class Circle extends Shape {
    String type = "Round Circle";

    public void displayBothTypes() {
        System.out.println("Child type: " + type);
        System.out.println("Parent type: " + super.type);
    }
}

public class Main {
    public static void main(String[] args) {
        Circle c = new Circle();
        c.displayBothTypes();
    }
}

class Logger {
    public void log(String msg) {
        System.out.println("[BASE LOG] " + msg);
    }
}

class TimestampLogger extends Logger {
    @Override
    public void log(String msg) {
        super.log(msg);
        System.out.println("[TIMESTAMP] 12:00:00 UTC");
    }
}

public class Main {
    public static void main(String[] args) {
        TimestampLogger logger = new TimestampLogger();
        logger.log("System update complete.");
    }
}

