class Transaction {
    protected double amount;

    public Transaction(double amount) {
        this.amount = amount;
    }

    public double calculateFee() {
        return amount * 0.02;
    }
}

class InternationalTransaction extends Transaction {
    private double foreignExchangeFee;

    public InternationalTransaction(double amount, double fxFee) {
        super(amount);
        this.foreignExchangeFee = fxFee;
    }

    @Override
    public double calculateFee() {
        return super.calculateFee() + foreignExchangeFee;
    }

    public void printSummary() {
        System.out.println("Total fee: $" + calculateFee() + " on transaction of $" + amount);
    }
}

public class Main {
    public static void main(String[] args) {
        InternationalTransaction tx = new InternationalTransaction(1000.0, 15.0);
        tx.printSummary();
    }
}
